/**
 * city-common/library.js — the shared "student model library".
 * One catalog for every placeable 3D object across ALL scenarios (city, lab,
 * space, park…). The 2D planner drawer and the 3D builders read from here so a
 * model added once is usable everywhere.
 *
 * Schema:
 *   { id, name, emoji, glb, category, footprint:[w,d], height, anchors? }
 *   - glb:      path from the app root, e.g. '../library/buildings/x.glb'
 *   - footprint default metres [width, depth] (placement / collision). GLBs are
 *     stored in source units; consumers scale the model to this footprint (the
 *     same pattern the city's applyBuildingModel already uses).
 *   - height:   metres (placement hint)
 *   - anchors:  optional placement surface hints for future scenarios
 *               ('floor' | 'wall' | 'ceiling') — used by indoor build-modes
 */

