/** Lookup by id (safe against unknown keys). */
export function libraryItem(id) {
  return LIBRARY.find((e) => e.id === id) || null;
}

/** All entries in a category (for a drawer / palette). */
export function libraryByCategory(category) {
  return LIBRARY.filter((e) => e.category === category);
}

/**
 * R2-ready asset base. Empty = serve GLBs from the app origin (current setup,
 * relative '../library/...'). When the library grows to hundreds/thousands of
 * models, set this to the R2/Cloudflare CDN origin (e.g.
 * 'https://models.example.com/') and load via `libraryUrl(item)` — no other
 * code changes needed.
 */
export const LIBRARY_BASE = '';

/** Absolute URL for a library item's GLB (respects LIBRARY_BASE). */
export function libraryUrl(item) {
  if (!item) return '';
  if (LIBRARY_BASE) return LIBRARY_BASE.replace(/\/$/, '') + '/' + item.glb.replace(/^\.\.\//, '');
  return item.glb;
}
